function normalizeName(n) {
  return n.toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
}

function isAvailable(ujierNombre, dateStr, timeHint) {
  const normTarget = normalizeName(ujierNombre);
  let personData = null;
  for (const k of Object.keys(availabilityData)) {
    if (normalizeName(k) === normTarget) { personData = availabilityData[k]; break; }
  }
  if (!personData) return true;
  const dayData = personData[dateStr];
  if (!dayData) return true;
  if (timeHint && dayData[timeHint] !== undefined) return dayData[timeHint] === 1;
  if (dayData[''] !== undefined) return dayData[''] === 1;
  const vals = Object.values(dayData);
  return vals.some(v => v === 1);
}

function getDayType(dateStr) {
  const d = new Date(dateStr + 'T00:00:00');
  const dow = d.getDay();
  if (dow === 0) return 'Domingo';
  if (dow === 1) return 'Lunes';
  if (dow === 2) return 'Martes';
  if (dow === 3) return 'Miercoles';
  if (dow === 4) return 'Jueves';
  if (dow === 5) return 'Viernes';
  if (dow === 6) return 'Sabado';
  return null;
}

function getInitials(name) { return name.split(' ').slice(0,2).map(w=>w[0]).join(''); }

function getSkills(u) {
  let s = [];
  if (u.bienvenida) s.push('Bienvenida');
  if (u.banos) s.push('Baños');
  if (u.diezmos) s.push('Diezmos');
  if (u.escuela) s.push('Esc. Bíblica');
  if (u.anuncios) s.push('Anuncios');
  if (u.lider) s.push('Líder');
  if (u.aromatica) s.push('Aromática');
  if (u.cafe) s.push('Café');
  return s;
}

function pickOne(pool, serviceCounts, usedInSlot) {
  const avail = pool.filter(u => !usedInSlot.has(u.id));
  if (!avail.length) return pool.slice().sort((a,b) => serviceCounts[a.id]-serviceCounts[b.id])[0];
  return avail.slice().sort((a,b) => serviceCounts[a.id]-serviceCounts[b.id] || (a.nombre>b.nombre?1:-1))[0];
}

function generateMonthSchedule(year, month) {
  const key = `${year}-${month}`;
  if (generatedSchedule[key]) return generatedSchedule[key];
  const schedule = {};
  const daysInMonth = new Date(year, month+1, 0).getDate();
  const serviceCounts = {};
  UJIERES.forEach(u => serviceCounts[u.id] = 0);

  function assignServices(slotKey, dayType, dateStr) {
    if (!SERVICIOS_POR_DIA[dayType]) return;
    schedule[slotKey] = { dayType, assignments: {} };
    const services = SERVICIOS_POR_DIA[dayType];
    const usedInSlot = new Set();
    let bienvenida2Person = null;
    let banosPersonId = null;
    let liderPersonId = null;
    const aleida = UJIERES.find(u => u.id === ALEIDA_ID);
    const aleidaAvail = isAvailable(aleida.nombre, dateStr, '');

    for (const serv of services) {
      if (manualAssignments[`${slotKey}__${serv}`]) {
        schedule[slotKey].assignments[serv] = manualAssignments[`${slotKey}__${serv}`];
        const u = UJIERES.find(x => x.nombre === manualAssignments[`${slotKey}__${serv}`]);
        if (u) usedInSlot.add(u.id);
        continue;
      }
      const sk = SKILL_MAP[serv];
      if (!sk) continue;
      if (serv === 'DIEZMOS Y OFRENDAS 1' && bienvenida2Person) {
        schedule[slotKey].assignments[serv] = bienvenida2Person.nombre;
        continue;
      }
      if (serv === 'DIEZMOS Y OFRENDAS 2' && banosPersonId !== null) {
        const p = UJIERES.find(u => u.id === banosPersonId);
        if (p) { schedule[slotKey].assignments[serv] = p.nombre; continue; }
      }
      if (serv === 'ANUNCIOS' && liderPersonId !== null) {
        const p = UJIERES.find(u => u.id === liderPersonId);
        if (p) { schedule[slotKey].assignments[serv] = p.nombre; continue; }
      }
      if (serv === 'LIDER DE UJIERES' && liderPersonId !== null) {
        const p = UJIERES.find(u => u.id === liderPersonId);
        if (p) { schedule[slotKey].assignments[serv] = p.nombre; continue; }
      }
      let candidates = UJIERES.filter(u => u[sk] === 1 && isAvailable(u.nombre, dateStr, ''));
      if (serv === 'BIENVENIDA 1') {
        const maleCandidates = candidates.filter(u => u.sexo === 'M');
        if (maleCandidates.length > 0) candidates = maleCandidates;
      }
      const fallbackCandidates = UJIERES.filter(u => u[sk] === 1);
      const isFallback = candidates.length === 0;
      const pool = isFallback ? fallbackCandidates : candidates;
      if (!pool.length) continue;
      let chosen;
      if (aleidaAvail && pool.find(u => u.id === ALEIDA_ID) && !usedInSlot.has(ALEIDA_ID)) {
        chosen = aleida;
      } else {
        chosen = pickOne(pool, serviceCounts, usedInSlot);
      }
      if (!chosen) continue;
      schedule[slotKey].assignments[serv] = chosen.nombre + (isFallback ? ' ⚠' : '');
      serviceCounts[chosen.id]++;
      usedInSlot.add(chosen.id);
      if (serv === 'BIENVENIDA 2') bienvenida2Person = chosen;
      if (serv === 'BAÑOS') banosPersonId = chosen.id;
      if (serv === 'LIDER DE UJIERES') liderPersonId = chosen.id;
    }
  }

  for (let d = 1; d <= daysInMonth; d++) {
    const dateStr = `${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    const base = getDayType(dateStr);
    if (!base) continue;
    if (base === 'Jueves') {
      assignServices(dateStr + '_AM', 'Jueves AM', dateStr);
      assignServices(dateStr + '_PM', 'Jueves PM', dateStr);
    } else if (base === 'Sabado') {
      assignServices(dateStr + '_AM', 'Sabado AM', dateStr);
      assignServices(dateStr + '_PM', 'Sabado PM', dateStr);
    } else {
      assignServices(dateStr, base, dateStr);
    }
  }
  generatedSchedule[key] = schedule;
  return schedule;
}

function slotToDate(slotKey) { return slotKey.replace(/_AM$|_PM$/,''); }

function renderCalendar() {
  const schedule = generateMonthSchedule(currentYear, currentMonth);
  const daysInMonth = new Date(currentYear, currentMonth+1, 0).getDate();
  const firstDay = new Date(currentYear, currentMonth, 1).getDay();
  const months = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
  document.getElementById('month-title').textContent = `${months[currentMonth]} ${currentYear}`;
  const today = new Date();
  let html = '<div class="month-grid">';
  ['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'].forEach(d => { html += `<div class="dow-label">${d}</div>`; });
  for (let i=0; i<firstDay; i++) html += '<div class="day-cell empty"></div>';
  for (let d=1; d<=daysInMonth; d++) {
    const dateStr = `${currentYear}-${String(currentMonth+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    const base = getDayType(dateStr);
    const slots = base==='Jueves'?[dateStr+'_AM',dateStr+'_PM']:base==='Sabado'?[dateStr+'_AM',dateStr+'_PM']:base?[dateStr]:[];
    const hasService = slots.some(s => schedule[s]);
    const isToday = today.getFullYear()===currentYear && today.getMonth()===currentMonth && today.getDate()===d;
    let cls = 'day-cell'; if (isToday) cls += ' today'; if (hasService) cls += ' has-service';
    let chips = ''; let totalServs = 0;
    slots.forEach(sk => {
      if (!schedule[sk]) return;
      const servKeys = Object.keys(schedule[sk].assignments);
      totalServs += servKeys.length;
      if (chips.split('service-chip').length - 1 < 3) {
        servKeys.slice(0, Math.max(1, 3 - chips.split('service-chip').length + 1)).forEach(s => {
          const isCafe = s.includes('CAFE')||s.includes('AROMATICA');
          chips += `<span class="service-chip${isCafe?' cafe':''}">${schedule[sk].dayType.replace('Sabado','Sab.')} ${s}</span>`;
        });
      }
    });
    if (totalServs > 3) chips += `<span class="service-chip" style="background:#e0e0e0;color:#666">+${totalServs-3}</span>`;
    html += `<div class="${cls}" onclick="showDayDetail('${dateStr}')"><div class="day-num">${d}${hasService?'<span class="service-dot"></span>':''}</div>${chips}</div>`;
  }
  html += '</div>';
  document.getElementById('month-grid-container').innerHTML = html;
}

function showDayDetail(dateStr) {
  const schedule = generateMonthSchedule(currentYear, currentMonth);
  const base = getDayType(dateStr);
  const detail = document.getElementById('day-detail');
  const d = new Date(dateStr + 'T00:00:00');
  const opts = {weekday:'long', year:'numeric', month:'long', day:'numeric'};
  const slots = base==='Jueves'?[dateStr+'_AM',dateStr+'_PM']:base==='Sabado'?[dateStr+'_AM',dateStr+'_PM']:base?[dateStr]:[];
  const hasAny = slots.some(s => schedule[s]);
  if (!hasAny) { detail.style.display='none'; return; }
  detail.style.display = 'block';
  document.getElementById('day-detail-title').textContent = `Servicios del ${d.toLocaleDateString('es-CO', opts)}`;
  let html = '';
  slots.forEach(sk => {
    if (!schedule[sk]) return;
    html += `<p style="font-size:12px;font-weight:500;color:#8B1A1A;margin:10px 0 6px">${schedule[sk].dayType}</p>`;
    html += '<table><tr><th>Servicio</th><th>Ujier asignado</th></tr>';
    Object.entries(schedule[sk].assignments).forEach(([s,u]) => {
      const warn = u.endsWith(' ⚠');
      html += `<tr><td>${s}</td><td><span class="badge badge-service" style="${warn?'background:rgba(201,162,39,0.15);color:#8a6a00':''}">${u}</span>${warn?'<span style="font-size:10px;color:#8a6a00;margin-left:4px">Sin disponibles</span>':''}</td></tr>`;
    });
    html += '</table>';
  });
  document.getElementById('day-detail-content').innerHTML = html;
}

function changeMonth(dir) {
  currentMonth += dir;
  if (currentMonth > 11) { currentMonth = 0; currentYear++; }
  if (currentMonth < 0) { currentMonth = 11; currentYear--; }
  generatedSchedule = {};
  renderCalendar();
  document.getElementById('day-detail').style.display='none';
}

function showPanel(name, el) {
  document.querySelectorAll('.panel').forEach(p => p.classList.remove('active'));
  document.querySelectorAll('.nav-btn').forEach(b => b.classList.remove('active'));
  document.getElementById('panel-'+name).classList.add('active');
  if (el) el.classList.add('active');
  if (name === 'persona') renderPersonaList('');
  if (name === 'ujieres') renderUjieresList('','');
  if (name === 'servicio') initServicioSelect();
  if (name === 'editar') initEditPanel();
}

function renderPersonaList(filter) {
  const list = UJIERES.filter(u => u.nombre.includes(filter.toUpperCase()));
  let html = '';
  list.forEach(u => {
    const skills = getSkills(u);
    html += `<div class="person-card" onclick="showPersonaDetail(${u.id})">
      <div class="avatar${u.lider?' lider':''}">${getInitials(u.nombre)}</div>
      <div class="person-info"><h3>${u.nombre}</h3>
      <div class="person-skills">${skills.map(s=>`<span class="skill-tag">${s}</span>`).join('')}</div></div>
    </div>`;
  });
  document.getElementById('personas-list').innerHTML = html || '<div class="no-results"><p>No se encontraron ujieres</p></div>';
}

function filterPersonas(v) { renderPersonaList(v); }

function showPersonaDetail(id) {
  const u = UJIERES.find(x => x.id === id);
  const det = document.getElementById('persona-detail');
  det.style.display = 'block';
  document.getElementById('persona-detail-name').textContent = u.nombre;
  const skills = getSkills(u);
  document.getElementById('persona-skills-row').innerHTML = skills.map(s=>`<span class="badge badge-service">${s}</span>`).join(' ');
  const schedule = generateMonthSchedule(currentYear, currentMonth);
  let rows = [];
  Object.entries(schedule).forEach(([slotKey, day]) => {
    Object.entries(day.assignments).forEach(([serv, nombre]) => {
      if (nombre.replace(' ⚠','') === u.nombre) {
        const dateStr = slotToDate(slotKey);
        const d = new Date(dateStr + 'T00:00:00');
        rows.push({slotKey, serv, dayType: day.dayType, d});
      }
    });
  });
  rows.sort((a,b) => a.d - b.d);
  if (!rows.length) { document.getElementById('persona-schedule').innerHTML = '<div class="no-results"><p>No tiene servicios asignados este mes</p></div>'; return; }
  let html = `<table><tr><th>Fecha</th><th>Tipo de día</th><th>Servicio</th></tr>`;
  rows.forEach(r => {
    const opts = {weekday:'short', day:'numeric', month:'short'};
    html += `<tr><td>${r.d.toLocaleDateString('es-CO', opts)}</td><td>${r.dayType}</td><td><span class="badge badge-service">${r.serv}</span></td></tr>`;
  });
  html += `</table><p style="font-size:12px; color:#666; margin-top:8px;">Total servicios este mes: <b>${rows.length}</b></p>`;
  document.getElementById('persona-schedule').innerHTML = html;
}

function initServicioSelect() {
  const sel = document.getElementById('select-servicio');
  const selDia = document.getElementById('select-dia-serv');
  if (sel.options.length > 1) return;
  const allServs = new Set();
  Object.values(SERVICIOS_POR_DIA).flat().forEach(s => allServs.add(s));
  allServs.forEach(s => { const o = document.createElement('option'); o.value=s; o.textContent=s; sel.appendChild(o); });
  Object.keys(SERVICIOS_POR_DIA).forEach(d => { const o = document.createElement('option'); o.value=d; o.textContent=d; selDia.appendChild(o); });
}

function filterServicio() {
  const serv = document.getElementById('select-servicio').value;
  const dia = document.getElementById('select-dia-serv').value;
  if (!serv) { document.getElementById('servicio-results').innerHTML = '<div class="no-results"><p>Selecciona un servicio para ver los asignados</p></div>'; return; }
  const schedule = generateMonthSchedule(currentYear, currentMonth);
  let rows = [];
  Object.entries(schedule).forEach(([slotKey, day]) => {
    if (dia && day.dayType !== dia) return;
    if (day.assignments[serv]) { const dateStr=slotToDate(slotKey); const d=new Date(dateStr+'T00:00:00'); rows.push({slotKey, nombre: day.assignments[serv], dayType: day.dayType, d}); }
  });
  rows.sort((a,b) => a.d - b.d);
  if (!rows.length) { document.getElementById('servicio-results').innerHTML = '<div class="no-results"><p>Sin asignaciones encontradas</p></div>'; return; }
  let html = `<table><tr><th>Fecha</th><th>Jornada</th><th>Ujier</th></tr>`;
  rows.forEach(r => { const opts={weekday:'short',day:'numeric',month:'short'}; html+=`<tr><td>${r.d.toLocaleDateString('es-CO', opts)}</td><td>${r.dayType}</td><td><span class="badge badge-service">${r.nombre}</span></td></tr>`; });
  html += `</table>`;
  document.getElementById('servicio-results').innerHTML = html;
}

function filterDia() {
  const dateVal = document.getElementById('search-dia').value;
  if (!dateVal) { document.getElementById('dia-results').innerHTML = '<div class="no-results"><p>Selecciona una fecha</p></div>'; return; }
  const d = new Date(dateVal + 'T00:00:00');
  const schedule = generateMonthSchedule(d.getFullYear(), d.getMonth());
  const base = getDayType(dateVal);
  const slots = base==='Jueves'?[dateVal+'_AM',dateVal+'_PM']:base==='Sabado'?[dateVal+'_AM',dateVal+'_PM']:base?[dateVal]:[];
  const hasAny = slots.some(s => schedule[s]);
  if (!hasAny) { document.getElementById('dia-results').innerHTML = '<div class="no-results"><p>No hay servicios programados para ese día</p></div>'; return; }
  let html = '';
  slots.forEach(sk => {
    if (!schedule[sk]) return;
    html += `<p style="font-size:13px;color:#666;margin-bottom:8px;">Tipo de día: <b>${schedule[sk].dayType}</b></p>`;
    html += `<table><tr><th>Servicio</th><th>Ujier asignado</th></tr>`;
    Object.entries(schedule[sk].assignments).forEach(([s,u]) => { html+=`<tr><td>${s}</td><td><span class="badge badge-service">${u}</span></td></tr>`; });
    html += `</table><br>`;
  });
  document.getElementById('dia-results').innerHTML = html;
}

function renderUjieresList(nameFilter, skillFilter) {
  let list = UJIERES.filter(u => {
    const nm = nameFilter ? u.nombre.includes(nameFilter.toUpperCase()) : true;
    let sk = true;
    if (skillFilter === 'bienvenida') sk = u.bienvenida;
    else if (skillFilter === 'diezmos') sk = u.diezmos;
    else if (skillFilter === 'anuncios') sk = u.anuncios;
    else if (skillFilter === 'lider') sk = u.lider;
    else if (skillFilter === 'aromatica') sk = u.aromatica;
    else if (skillFilter === 'cafe') sk = u.cafe;
    return nm && sk;
  });
  document.getElementById('stat-lideres').textContent = UJIERES.filter(u=>u.lider).length;
  document.getElementById('stat-bienvenida').textContent = UJIERES.filter(u=>u.bienvenida).length;
  document.getElementById('stat-diezmos').textContent = UJIERES.filter(u=>u.diezmos).length;
  let html = '';
  list.forEach(u => {
    const skills = getSkills(u);
    html += `<div class="person-card">
      <div class="avatar${u.lider?' lider':''}">${getInitials(u.nombre)}</div>
      <div class="person-info" style="flex:1">
        <h3>${u.nombre}</h3>
        <div class="person-skills">${skills.map(s=>`<span class="skill-tag">${s}</span>`).join('')||'<span class="skill-tag">Sin roles</span>'}</div>
      </div>
    </div>`;
  });
  document.getElementById('ujieres-list').innerHTML = html || '<div class="no-results"><p>Sin resultados</p></div>';
}

function filterUjieres() {
  const nf = document.getElementById('search-ujier').value;
  const sf = document.getElementById('filter-skill').value;
  renderUjieresList(nf, sf);
}

function initEditPanel() {
  const selServ = document.getElementById('edit-servicio-tipo');
  const selUjier = document.getElementById('edit-ujier');
  if (selServ.options.length === 0) {
    const allServs = new Set(Object.values(SERVICIOS_POR_DIA).flat());
    allServs.forEach(s => { const o = document.createElement('option'); o.value=s; o.textContent=s; selServ.appendChild(o); });
  }
  if (selUjier.options.length === 0) {
    UJIERES.forEach(u => { const o = document.createElement('option'); o.value=u.nombre; o.textContent=u.nombre; selUjier.appendChild(o); });
  }
}

function saveEdit() {
  const fecha = document.getElementById('edit-fecha').value;
  const diaTipo = document.getElementById('edit-dia-tipo').value;
  const serv = document.getElementById('edit-servicio-tipo').value;
  const ujier = document.getElementById('edit-ujier').value;
  if (!fecha || !serv || !ujier) return;
  const suffix = diaTipo.endsWith('AM') ? '_AM' : diaTipo.endsWith('PM') ? '_PM' : '';
  const slotKey = fecha + suffix;
  manualAssignments[`${slotKey}__${serv}`] = ujier;
  generatedSchedule = {};
  const msg = document.getElementById('edit-msg');
  msg.innerHTML = `<div class="success-msg">Cambio guardado: ${ujier} → ${serv} el ${fecha} (${diaTipo})</div>`;
  renderManualList();
  setTimeout(() => msg.innerHTML = '', 3000);
}

function clearEdit() { document.getElementById('edit-fecha').value = ''; document.getElementById('edit-msg').innerHTML = ''; }

function renderManualList() {
  const keys = Object.keys(manualAssignments);
  if (!keys.length) { document.getElementById('manual-list').innerHTML = '<div class="no-results"><p>Aún no hay ediciones manuales</p></div>'; return; }
  let html = `<table><tr><th>Fecha / Jornada</th><th>Servicio</th><th>Ujier</th><th></th></tr>`;
  keys.forEach(k => {
    const [f,s] = k.split('__');
    html += `<tr><td>${f}</td><td>${s}</td><td>${manualAssignments[k]}</td><td><button class="btn btn-secondary" style="padding:3px 8px;font-size:11px" onclick="deleteManual('${k}')">Eliminar</button></td></tr>`;
  });
  html += '</table>';
  document.getElementById('manual-list').innerHTML = html;
}

function deleteManual(key) { delete manualAssignments[key]; generatedSchedule = {}; renderManualList(); }

function exportExcel() {
  const schedule = generateMonthSchedule(currentYear, currentMonth);
  const months = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
  let csv = `Programación Ujieres - ${months[currentMonth]} ${currentYear}\n\n`;
  csv += 'Fecha,Jornada,Servicio,Ujier asignado\n';
  Object.entries(schedule).sort().forEach(([slotKey, day]) => {
    const dateStr = slotToDate(slotKey);
    const d = new Date(dateStr + 'T00:00:00');
    const dateLabel = d.toLocaleDateString('es-CO');
    Object.entries(day.assignments).forEach(([serv, ujier]) => {
      csv += `${dateLabel},${day.dayType},"${serv}","${ujier}"\n`;
    });
  });
  const blob = new Blob(['\ufeff'+csv], {type:'text/csv;charset=utf-8;'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = `ujieres_${months[currentMonth]}_${currentYear}.csv`;
  a.click(); URL.revokeObjectURL(url);
}

function loadAvailability(input) {
  const file = input.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = function(e) {
    try {
      const data = new Uint8Array(e.target.result);
      const wb = XLSX.read(data, {type: 'array', cellDates: true});
      const sheetName = wb.SheetNames[0];
      const ws = wb.Sheets[sheetName];
      const raw = XLSX.utils.sheet_to_json(ws, {header:1, defval: 0, raw: false});
      const dateRow = raw[1] || [];
      const timeRow = raw[2] || [];
      const newAvail = {};
      const cols = {};
      for (let i = 1; i < dateRow.length; i++) {
        let dv = dateRow[i];
        if (!dv) continue;
        let dateStr = '';
        if (dv instanceof Date) { dateStr = dv.toISOString().slice(0,10); }
        else if (typeof dv === 'string') {
          const m = dv.match(/(\d{4})-(\d{2})-(\d{2})/);
          if (m) dateStr = m[0];
          else { const d2 = new Date(dv); if (!isNaN(d2)) dateStr = d2.toISOString().slice(0,10); }
        } else if (typeof dv === 'number') {
          const d2 = new Date((dv - 25569) * 86400 * 1000);
          dateStr = d2.toISOString().slice(0,10);
        }
        if (!dateStr) continue;
        const timeLabel = (timeRow[i] || '').toString().trim().toLowerCase();
        cols[i] = {date: dateStr, time: timeLabel};
      }
      for (let ri = 3; ri < raw.length; ri++) {
        const row = raw[ri];
        const name = (row[0] || '').toString().trim().toUpperCase();
        if (!name || name === '0') continue;
        newAvail[name] = {};
        for (const [ci, colInfo] of Object.entries(cols)) {
          const {date, time} = colInfo;
          if (!newAvail[name][date]) newAvail[name][date] = {};
          const val = parseInt(row[ci]) || 0;
          newAvail[name][date][time || ''] = val;
        }
      }
      if (Object.keys(newAvail).length > 0) {
        availabilityData = newAvail;
        generatedSchedule = {};
        renderCalendar();
        const banner = document.getElementById('upload-banner');
        document.getElementById('upload-msg').textContent = `Disponibilidad cargada: ${Object.keys(newAvail).length} personas · ${sheetName}. La programación se actualizó.`;
        banner.classList.add('show');
        setTimeout(() => banner.classList.remove('show'), 6000);
      } else {
        alert('No se encontraron datos de disponibilidad en el archivo. Verifica el formato.');
      }
    } catch(err) {
      alert('Error leyendo el archivo: ' + err.message);
    }
    input.value = '';
  };
  reader.readAsArrayBuffer(file);
}

renderCalendar();
